(function(){"use strict";const cfg=window.CHATBOT_CONFIG||{};const{apiUrl,suggestionsUrl,historyUrl}=cfg;const widget=document.getElementById("chat-widget");const toggle=document.getElementById("chat-toggle");const panel=document.getElementById("chat-panel");const closeBtn=document.getElementById("chat-close");const form=document.getElementById("chat-form");const input=document.getElementById("chat-input");const messages=document.getElementById("chat-messages");const suggestionsEl=document.getElementById("chat-suggestions");if(!widget||!toggle||!panel)return;let greeted=false;let restored=false;function getCookie(name){const m=document.cookie.match(new RegExp("(^|;\\s*)"+name+"=([^;]*)"));return m?decodeURIComponent(m[2]):"";}function openPanel(){widget.classList.add("is-open");toggle.setAttribute("aria-expanded","true");toggle.classList.remove("is-idle");const badge=toggle.querySelector(".badge");if(badge)badge.hidden=true;greet();setTimeout(()=>input&&input.focus(),180);}function closePanel(){widget.classList.remove("is-open");toggle.setAttribute("aria-expanded","false");}function togglePanel(){widget.classList.contains("is-open")?closePanel():openPanel();}function buildLinksBar(links){const bar=document.createElement("div");bar.className="msg-links";links.forEach((l)=>{const a=document.createElement("a");a.href=l.url;a.textContent=l.label;if(l.new_tab){a.target="_blank";a.rel="noopener noreferrer";}bar.appendChild(a);});return bar;}function addMessage(text,who="bot",topic=null,links=[]){const el=document.createElement("div");el.className="msg "+who;el.textContent=text;if(topic){const t=document.createElement("span");t.className="topic";t.textContent=topic;el.appendChild(t);}if(links&&links.length){el.appendChild(buildLinksBar(links));}messages.appendChild(el);messages.scrollTop=messages.scrollHeight;return el;}function addTypingBubble(){const el=document.createElement("div");el.className="msg bot typing";el.innerHTML='<span class="dot"></span><span class="dot"></span><span class="dot"></span>';el.setAttribute("aria-label","Assistant is typing");messages.appendChild(el);messages.scrollTop=messages.scrollHeight;return el;}function replaceTypingWith(el,text,topic=null,links=[]){el.classList.add("fade-out");setTimeout(()=>{el.classList.remove("typing","fade-out");el.classList.add("fade-in");el.textContent=text;if(topic){const t=document.createElement("span");t.className="topic";t.textContent=topic;el.appendChild(t);}if(links&&links.length){el.appendChild(buildLinksBar(links));}messages.scrollTop=messages.scrollHeight;},160);}function renderSuggestions(items){if(!suggestionsEl)return;suggestionsEl.innerHTML="";const groups={};items.forEach((it)=>{const key=it.topic||"Popular";(groups[key]||=[]).push(it.question);});Object.entries(groups).forEach(([topic,questions])=>{const wrap=document.createElement("div");wrap.className="sugg-group";const label=document.createElement("div");label.className="sugg-label";label.textContent=topic;wrap.appendChild(label);const chips=document.createElement("div");chips.className="sugg-chips";questions.forEach((q)=>{const b=document.createElement("button");b.type="button";b.textContent=q;b.addEventListener("click",()=>send(q));chips.appendChild(b);});wrap.appendChild(chips);suggestionsEl.appendChild(wrap);});}async function send(message){addMessage(message,"user");input.value="";if(suggestionsEl)suggestionsEl.innerHTML="";const typing=addTypingBubble();try{const res=await fetch(apiUrl,{method:"POST",headers:{"Content-Type":"application/json","X-CSRFToken":getCookie("csrftoken"),},credentials:"same-origin",body:JSON.stringify({message}),});const data=await res.json();replaceTypingWith(typing,data.reply,data.topic,data.links||[]);if(data.suggestions&&data.suggestions.length){renderSuggestions(data.suggestions);}}catch(e){replaceTypingWith(typing,"Sorry, something went wrong. Please try again.");}}async function restoreHistory(){if(restored)return false;restored=true;try{const res=await fetch(historyUrl,{credentials:"same-origin",});const data=await res.json();if(data.messages&&data.messages.length){data.messages.forEach((m)=>addMessage(m.text,m.role));return true;}}catch(_){}return false;}async function greet(){if(greeted)return;greeted=true;const hadHistory=await restoreHistory();if(hadHistory)return;addMessage("Hi! I can help with insurance products, coverage, claims, and pricing. What would you like to know?");try{const res=await fetch(suggestionsUrl,{credentials:"same-origin"});const data=await res.json();if(data.suggestions)renderSuggestions(data.suggestions);}catch(_){}}toggle.addEventListener("click",togglePanel);closeBtn.addEventListener("click",closePanel);document.addEventListener("keydown",(e)=>{if(e.key==="Escape"&&widget.classList.contains("is-open")){closePanel();}});form.addEventListener("submit",(e)=>{e.preventDefault();const msg=input.value.trim();if(msg)send(msg);});toggle.classList.add("is-idle");toggle.setAttribute("aria-expanded","false");})();;